-- Phase 1 QA: align the DB with the shared Zod schemas (packages/shared is the source of truth).
-- Generated by drizzle-kit, then edited by hand:
--   * rebuild INSERT ... SELECTs list only columns that exist in the old tables (drizzle-kit
--     also listed the new ones, which fails with "no such column");
--   * legacy literals are mapped: cv_versions.language 'EN'/'VI' -> 'en'/'vi', rooms.kind
--     'consult' -> 'direct', unknown engine_state.reason -> 'usage_limit'.
-- PRAGMA foreign_keys is a no-op inside the migrator's transaction; openDb() turns foreign
-- keys off around the whole migration and runs foreign_key_check before turning them on.
PRAGMA foreign_keys=OFF;--> statement-breakpoint
CREATE TABLE `__new_cv_versions` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`job_id` integer NOT NULL,
	`language` text NOT NULL,
	`round` integer NOT NULL,
	`tailored_json` text,
	`figma_frame_name` text,
	`figma_frame_url` text,
	`pdf_path` text,
	`pdf_sha256` text,
	`change_notes_json` text DEFAULT '[]' NOT NULL,
	`fact_requests_json` text DEFAULT '[]' NOT NULL,
	`master_version` integer,
	`prompt_version` integer,
	`created_at` text NOT NULL,
	FOREIGN KEY (`job_id`) REFERENCES `jobs`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "cv_versions_language_check" CHECK("language" IS NULL OR "language" IN ('en', 'vi'))
);
--> statement-breakpoint
